questionvariables.text:
/*randomizing the coefficients of in the sequence*/
aa:-1*(rand(3)+1);
bb:rand(3)+2;
cc:rand(3)+3;

/*randomizing the nth term entries*/
x:[-1,0,1,2,3];
y:[1,2,3,4,5];
z:[3,4,5,6,7];
q:rand([x,y,z]);

w[n]:=((aa)^(n+1))/(bb*n+(cc)^n); /*The sequence*/
w[0];
w[1];
ta1:w[q[1]]; /*the first 5 terms of the sequence*/
ta2:w[q[2]];
ta3:w[q[3]];
ta4:w[q[4]];
ta5:w[q[5]];
w[inf];
ta:[ta1,ta2,ta3,ta4,ta5];

/*Worked soln*/
expr1:((aa)^(q[1]+1))/(bb*q[1]+(cc)^q[1]); 
expr2:((aa)^(q[2]+1))/(bb*q[2]+(cc)^q[2]); 
expr3:((aa)^(q[3]+1))/(bb*q[3]+(cc)^q[3]); 
expr4:((aa)^(q[4]+1))/(bb*q[4]+(cc)^q[4]); 
expr5:((aa)^(q[5]+1))/(bb*q[5]+(cc)^q[5]);

feedbackvariables.text:
/*node 1 checks for correct answer*/
